package cn.iocoder.yudao.module.zsjos.dal.mysql.positioning; import cn.iocoder.yudao.framework.mybatis.core.mapper.BaseMapperX; import cn.iocoder.yudao.module.zsjos.dal.dataobject.positioning.PositioningCardVersionDO; import org.apache.ibatis.annotations.Mapper; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import java.util.List; @Mapper public interface PositioningCardVersionMapper extends BaseMapperX<PositioningCardVersionDO>{default List<PositioningCardVersionDO> selectByCard(Long id){return selectList(new LambdaQueryWrapper<PositioningCardVersionDO>().eq(PositioningCardVersionDO::getPositioningCardId,id).orderByDesc(PositioningCardVersionDO::getVersionNo));}}
